mapper.select:
SELECT r.id, r.environment, r.collection_id AS collectionId, c.name AS collectionName, r.total, r.passed, r.failed, r.blocked, r.duration_ms AS durationMs, r.ok, r.message, r.created_by AS createdBy, r.created_at AS createdAt FROM api_test_runs r LEFT JOIN api_test_collections c ON c.id = r.collection_id
r.collection_id = #{collectionId}
ORDER BY r.created_at DESC LIMIT #{limit}
